let dbPromise,installEvent;
const database=()=>dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('ghifar-offline-v2',1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function get(key){const db=await database();return new Promise((resolve,reject)=>{const r=db.transaction('kv').objectStore('kv').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function put(key,value){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function del(key){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const key=s=>s.workspace+':'+(s.user||s.email);
async function mutateQueue(s,change){const db=await database(),k='queue:'+key(s);return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite'),store=tx.objectStore('kv'),r=store.get(k);r.onsuccess=()=>{try{store.put(change(r.result||[]),k)}catch(e){tx.abort();reject(e)}};r.onerror=()=>reject(r.error);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
export const offlineStore={async enabled(s){return !!s&&!!await get('enabled:'+key(s))},async enable(s){await put('enabled:'+key(s),true)},async cache(s,data,revision){if(!s||!await this.enabled(s))return;await put('state:'+key(s),{session:s,data,revision,saved:new Date().toISOString()});await put('last',key(s))},async last(){const k=await get('last');return k?get('state:'+k):null},async queue(s){return await get('queue:'+key(s))||[]},async add(s,command){await mutateQueue(s,q=>q.some(e=>e.id===command.id)?q:[...q,{...command,status:'Menunggu',queued:new Date().toISOString()}])},async remove(s,id){await mutateQueue(s,q=>q.filter(e=>e.id!==id))},async update(s,id,v){await mutateQueue(s,q=>q.map(e=>e.id===id?{...e,...v}:e))},async disable(s){if((await this.queue(s)).length)throw Error('Sinkronkan atau hapus draft antrean dahulu');for(const p of ['enabled:','state:','queue:'])await del(p+key(s));if(await get('last')===key(s))await del('last')},async signout(s){if(s&&await this.enabled(s).catch(()=>false))await this.disable(s)}};
export async function setupPWA(){window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e});window.addEventListener('appinstalled',()=>installEvent=null);if('serviceWorker' in navigator)try{await navigator.serviceWorker.register('/service-worker.js',{scope:'/'})}catch(e){console.warn(e.message)}}
export async function installPWA(){if(!installEvent)throw Error('Gunakan menu browser → Instal aplikasi / Tambahkan ke layar utama jika tersedia.');await installEvent.prompt();await installEvent.userChoice;installEvent=null}
